\end{defn}

\begin{defn}
  \ollabel{defn:enumerable}
  A set~$A$ is !!{enumerable} iff either $A = \emptyset$ or there is
  an enumeration of~$A$. We say that $A$ is !!{nonenumerable} iff $A$
  is not !!{enumerable}.
\end{defn}

\begin{defn}[التعداد، بصيغة نظرية المجموعات]
\emph{تعداد} مجموعة $A$ هو !!a{bijection} مداها $A$ ومجالها إما
مقطع ابتدائي من الأعداد الطبيعية $\{0, 1, \ldots, n\}$ {أو}
مجموعة الأعداد الطبيعية كلها~$\Nat$.
\end{defn}

\begin{defn}
  \ollabel{defn:enumerable}
  تكون المجموعة~$A$ !!{enumerable} إذا وفقط إذا تحقق أحد أمرين: إما
  $A = \emptyset$ أو أن يكون لـ~$A$ تعداد. ونقول إن $A$
  !!{nonenumerable} إذا وفقط إذا لم
  تكن $A$ !!{enumerable}.
\end{defn}

\begin{defn}[التعداد في اصطلاح نظرية المجموعات]
\emph{تعداد} المجموعة $A$ هو !!a{bijection} مداها $A$، ومجالها مقطع ابتدائي من الأعداد الطبيعية $\{0, 1, \ldots, n\}$ {أو} مجموعة الأعداد الطبيعية كلها~$\Nat$.
\end{defn}

\begin{defn}
\ollabel{defn:enumerable}
المجموعة~$A$ !!{enumerable} إذا وفقط إذا كان $A = \emptyset$ أو وجد لـ~$A$ تعداد. وأما $A$ فتسمى !!{nonenumerable} إذا وفقط إذا لم تكن $A$ !!{enumerable}.
\end{defn}

